from pathlib import Path
p=Path('C:/Nori/streaming/producer.html')
s=p.read_text(encoding='utf-8')
backup=p.with_name('producer.before-local-answers.html')
if not backup.exists(): backup.write_text(s,encoding='utf-8')
s=s.replace('<section><h2>Moderator\'s desk</h2>', '''<section><h2>Local Nori answers</h2><p class="notice">Export one queued question, then drag that file onto <strong>tools/Connect-Nori-Answer.cmd</strong>. The local engine generates a reply file. Load it below and review the answer before copying it into chat.</p><label>Load Nori answer <input id="answer-file" type="file" accept=".json,application/json"></label><p id="answer-status" aria-live="polite">No answer loaded. This panel does not monitor live chat.</p><textarea id="nori-answer" rows="5" readonly aria-label="Nori answer for review"></textarea><button id="answer-to-draft">Use answer as message draft</button></section>\n<section><h2>Moderator's desk</h2>''')
s=s.replace('row.append(span,done,remove);box.append(row)', "const ask=document.createElement('button');ask.textContent='Export for Nori';ask.onclick=()=>downloadJson({question:q.text,topic:''},'nori-viewer-question.json');row.append(span,ask,done,remove);box.append(row)")
s=s.replace('This panel does not connect to Nori, YouTube or OBS.', 'Nori answers use selected-question files. This panel has no live connection to Nori, YouTube or OBS.')
s=s.replace('renderScenes();renderQuestions();renderClips();tick();', '''function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let reviewedAnswer=null;
function acceptNoriAnswer(data){if(!data||typeof data.question!=='string'||data.question.length>600||typeof data.answer!=='string'||!data.answer.trim()||data.answer.length>8000||data.localOnly!==true||data.postedToChat!==false||data.obsControlled!==false)throw new Error('Invalid local answer file');if(!state.questions.some(q=>q.text===data.question))throw new Error('This answer does not match a queued question');reviewedAnswer=data;document.querySelector('#nori-answer').value=data.answer;document.querySelector('#answer-status').textContent='For: '+data.question+' — Review before using. Nothing posted.';}
document.querySelector('#answer-file').onchange=async e=>{reviewedAnswer=null;document.querySelector('#nori-answer').value='';try{const file=e.target.files[0];if(!file)return;if(file.size>16000)throw new Error('Answer file is too large');acceptNoriAnswer(JSON.parse(await file.text()))}catch(error){document.querySelector('#answer-status').textContent=error.message}};
document.querySelector('#answer-to-draft').onclick=()=>{if(!reviewedAnswer){document.querySelector('#answer-status').textContent='Load a matching Nori answer first.';return}state.draft=reviewedAnswer.answer;document.querySelector('#draft').value=state.draft;save();document.querySelector('#answer-status').textContent='Added to your editable draft. Nothing posted.'};
renderScenes();renderQuestions();renderClips();tick();''')
p.write_text(s,encoding='utf-8')
